import React, { useEffect, useState } from 'react';
import { applicationsAPI } from '../services/api';
import axios from 'axios';
import api from '../services/api';

interface Application {
  _id: string;
  vendor: string;
  name: string;
  version: string;
}

interface Advisory {
  _id: string;
  advisoryId: string;
  advisoryLink: string;
  product: string;
  issued: string;
  severity: string;
  synopsis: string;
}

// Advisory type definition
interface Advisory {
  advisory: string;
  synopsis: string;
  severity: string;
  products: string;
  publishDate: string;
  cves: string[];
  link: string;
}

const AdvisoriesTable: React.FC = () => {
  const [advisories, setAdvisories] = useState<Advisory[]>([]);
  const [severity, setSeverity] = useState('All');

  useEffect(() => {
    fetch('/rhel_security_advisories.json')
      .then(res => res.json())
      .then(data => setAdvisories(data.advisories));
  }, []);

  const severities = Array.from(new Set(advisories.map(a => a.severity))).filter(Boolean);
  const filtered = severity === 'All' ? advisories : advisories.filter(a => a.severity === severity);

  return (
    <div style={{ margin: '2rem 0' }}>
      <h2>RHEL Security Advisories</h2>
      <div style={{ marginBottom: '1rem' }}>
        <label>Filter by Severity: </label>
        <select value={severity} onChange={e => setSeverity(e.target.value)}>
          <option value="All">All</option>
          {severities.map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
      </div>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ borderCollapse: 'collapse', width: '100%' }}>
          <thead>
            <tr>
              <th>Advisory</th>
              <th>Synopsis</th>
              <th>Severity</th>
              <th>Products</th>
              <th>Publish Date</th>
              <th>CVEs</th>
              <th>Link</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map(adv => (
              <tr key={adv.advisory}>
                <td>{adv.advisory}</td>
                <td>{adv.synopsis}</td>
                <td>{adv.severity}</td>
                <td>{adv.products}</td>
                <td>{adv.publishDate}</td>
                <td style={{ maxWidth: 200, wordBreak: 'break-all' }}>{adv.cves.join(', ')}</td>
                <td><a href={adv.link} target="_blank" rel="noopener noreferrer">View</a></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const PatchMgmt: React.FC = () => {
  const [applications, setApplications] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [advisories, setAdvisories] = useState<Advisory[]>([]);
  const [advLoading, setAdvLoading] = useState(false);
  const [advError, setAdvError] = useState<string | null>(null);

  useEffect(() => {
    const fetchApplications = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await applicationsAPI.getAll();
        setApplications(res.data.applications || []);
      } catch (err: any) {
        setError(err.response?.data?.error || 'Failed to fetch applications');
      } finally {
        setLoading(false);
      }
    };
    fetchApplications();
  }, []);

  useEffect(() => {
    console.debug('[PatchMgmt] Component mounted');
    setAdvLoading(true);
    setAdvError(null);
    api.get('/patches/redhat')
      .then(res => {
        console.debug('[PatchMgmt] API response:', res.data);
        setAdvisories(res.data);
      })
      .catch((err) => {
        console.error('[PatchMgmt] Failed to load advisories:', err);
        setError('Failed to load advisories');
        setAdvisories([]);
      })
      .finally(() => {
        setLoading(false);
        console.debug('[PatchMgmt] Loading finished. Advisories:', advisories);
      });
  }, []);

  return (
    <div style={{ margin: '2rem 0' }}>
      <h2>Patch Management</h2>
      {/* Application Patch Management Table (existing) */}
      <div style={{ marginBottom: '2rem' }}>
        <h3>Applications Patch Management</h3>
        {loading ? (
          <div className="text-center text-gray-500 dark:text-gray-400 py-8">Loading...</div>
        ) : error ? (
          <div className="text-center text-red-500 py-8">{error}</div>
        ) : applications.length === 0 ? (
          <div className="text-center text-gray-500 dark:text-gray-400 py-8">No applications found</div>
        ) : (
          <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
            <thead>
              <tr>
                <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">S.No</th>
                {Object.keys(applications[0]).map((key) => (
                  <th key={key} className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">{key}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {applications.map((app, idx) => (
                <tr key={(app as any)._id || idx} className="hover:bg-gray-50 dark:hover:bg-gray-700">
                  <td className="px-4 py-2">{idx + 1}</td>
                  {Object.keys(applications[0]).map((key) => (
                    <td key={key} className="px-4 py-2">
                      {typeof (app as any)[key] === 'string' && (app as any)[key].startsWith('http') ? (
                        <a href={(app as any)[key]} target="_blank" rel="noopener noreferrer" className="text-blue-500 underline">{(app as any)[key]}</a>
                      ) : typeof (app as any)[key] === 'object' && (app as any)[key] !== null ? JSON.stringify((app as any)[key]) : (app as any)[key]}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      {/* Advisories Table */}
      <div>
        <h3>RHEL Security Advisories</h3>
        {advLoading && <div>Loading advisories...</div>}
        {advError && <div style={{ color: 'red' }}>{advError}</div>}
        {!advLoading && !advError && (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ borderCollapse: 'collapse', width: '100%' }}>
              <thead>
                <tr>
                  <th>Advisory</th>
                  <th>Synopsis</th>
                  <th>Severity</th>
                  <th>Products</th>
                  <th>Publish Date</th>
                  <th>CVEs</th>
                  <th>Link</th>
                </tr>
              </thead>
              <tbody>
                {advisories.map(adv => (
                  <tr key={adv.advisory}>
                    <td>{adv.advisory}</td>
                    <td>{adv.synopsis}</td>
                    <td>{adv.severity}</td>
                    <td>{adv.products}</td>
                    <td>{adv.publishDate}</td>
                    <td>{adv.cves && adv.cves.length > 0 ? adv.cves.join(', ') : '-'}</td>
                    <td><a href={adv.link} target="_blank" rel="noopener noreferrer">View</a></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default PatchMgmt;
